effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

    #define PI 3.14159
    #define	TAU 6.28318

    float vDrop(vec2 uv,float t)
    {
        uv.x = uv.x*128.0;						// H-Count
        float dx = fract(uv.x);
        uv.x = floor(uv.x);
        uv.y *= 0.05;							// stretch
        float o=sin(uv.x*215.4);				// offset
        float s=cos(uv.x*33.1)*.3 +.7;			// speed
        float trail = mix(95.0,35.0,s);			// trail length
        float yv = fract(uv.y + t*s + o) * trail;
        yv = 1.0/yv;
        yv = smoothstep(0.0,1.0,yv*yv);
        yv = sin(yv*PI)*(s*5.0);
        float d2 = sin(dx*PI);
        return yv*(d2*d2);
    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        // if (adaptive) { umefx = acScreenNorm; }
        // else { 
        umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        umefx.y*=acLayerSize.y/acLayerSize.x;
        // }

        // umefx /= (5.0+scale);
        umefx *= rot2m((0.0+angle)*0.0174533);
        umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/250.;


        /////////////////////////

    	vec4 fragColor;

    	vec2 p = umefx;
        p /= (scale-0.5);
        float d = length(p)+0.1;
    	p = vec2(atan(p.x, p.y) / PI, 2.5 / d);
        if (0.0>0.5)
        	p.y *= 0.5;
        float t =  progressa*0.4;
        vec3 col = vec3(color1.rgb) * vDrop(p,t);	// red
        col += vec3(color2.rgb) * vDrop(p,t+0.33);	// blue
        col += vec3(color3.rgb) * vDrop(p,t+0.66);	// green
    	fragColor = vec4(col*(d*d), 1.0);

    	vec4 comet;
    	vec2 uvX = umefx;
        uvX /= (scale-0.5);
    	uvX.y = 1.-uvX.y;
    	if (0.0>0.5)
            uvX.y = 1.0-uvX.y;					// V-flip

        vec3 colX = vec3(color1.rgb);		// Drop Colour
        uvX.x = uvX.x*64.0;						// H-Count
        float dxX = fract(uvX.x);
        uvX.x = floor(uvX.x);
        float tX =  progressa*0.4;
        uvX.y *= 0.15;							// stretch
        float oX=sin(uvX.x*215.4);				// offset
        float sX=cos(uvX.x*33.1)*.3 +.7;			// speed
        float trailX = mix(95.0,35.0,sX);			// trail length
        float yvX = fract(uvX.y + tX*sX + oX) * trailX;
        yvX = 1.0/yvX;
        yvX = smoothstep(0.0,1.0,yvX*yvX);
        yvX = sin(yvX*PI)*(sX*5.0);
        float d2X = sin(dxX*PI);
        yvX *= d2X*d2X;
        colX = colX*yvX;
        comet = vec4(colX,1.0);

        vec4 factor;
    	if ( typeComet==0 ) { factor = mix(texColorX,fragColor,alpha); }
    	else if ( typeComet==1 ) { factor = mix(texColorX,comet,alpha); }

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
